const CATS=['AllProducts','shoes','hoodies-sweaters','t-shirts','jackets','pants-shorts','headwear','accessories','electronics','other-stuff','jersey'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dec=s=>String(s??'').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").trim();
const imgURL=s=>{try{let u=new URL(s,ORIGIN);return ['cnfanshm.com','www.cnfanshm.com'].includes(u.hostname)&&u.pathname.startsWith('/uploads/')?u.href:''}catch{return ''}};
async function source(path){const r=await fetch(ORIGIN+path,{signal:AbortSignal.timeout(20000),headers:{'User-Agent':'Mozilla/5.0'},cf:{cacheTtl:180,cacheEverything:true}});if(!r.ok)throw Error('Source '+r.status);return r.text()}
function cards(html){return html.split(/<div class="product-card\b[^>]*>/).slice(1).map(h=>({path:h.match(/href="([^"#]+\.html)"/)?.[1],image:imgURL(h.match(/data-src="([^"]+)"/)?.[1]),name:dec(h.match(/<h3[^>]*>([\s\S]*?)<\/h3>/)?.[1]),price:h.match(/class="product-price">\s*([\d.]+)/)?.[1]})).filter(p=>p.path&&p.image&&p.name)}
function detail(html){const area=html.split('class="product-gallery"')[1]?.split('class="product-info"')[0]||'';const description=html.split('class="product-description"')[1]?.split('</div>')[0]||'';const p={name:dec(html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/)?.[1]),id:html.match(/class="product-id">\s*ID:\s*(\d+)/)?.[1],price:html.match(/class="product-price">\s*([\d.]+)/)?.[1],images:[...new Set([...((area+description).matchAll(/<img\b[^>]*>/g))].map(m=>imgURL(m[0].match(/data-src="([^"]+)"/)?.[1]||m[0].match(/src="([^"]+)"/)?.[1])).filter(Boolean))],original:dec(html.match(/href="(https?:\/\/(?:weidian\.com\/item\.html|item\.taobao\.com\/item\.htm|detail\.1688\.com\/offer\/)[^"]+)"/)?.[1]),agents:[]};
for(const m of html.matchAll(/<a\b([^>]*class="platform-option"[^>]*)>([\s\S]*?)<\/a>/g)){const url=dec(m[1].match(/href="([^"]+)"/)?.[1]);const label=dec(m[2].match(/<span[^>]*>([\s\S]*?)<\/span>/)?.[1]).replace(/\s+Link\s*$/i,'');try{const u=new URL(url);if(/^https?:$/.test(u.protocol)&&label&&p.id&&decodeURIComponent(url).includes(p.id))p.agents.push({name:label,url})}catch{}}
return p;}
const TITLE_PATTERN=new RegExp('\\b('+TITLE_ROWS.map(r=>r[0]).sort((a,b)=>b.length-a.length).join('|')+')\\b','gi');
function name(raw,l){const chineseTitles={'D木棉套装-01 Hoodie & Pants Se':'D Hoodie & Pants Set - 01','Global Find-BEE包包':'Global Find-BEE Bag','MX60小白鞋 Sneakers [23 styles]':'MX60 White Sneakers [23 styles]','加厚连帽情侣羽绒棉服':'Thick hooded padded jacket','新款时尚手镯':'New fashion bracelet','时尚百搭经典板鞋-CY':'Classic casual sneakers - CY','时尚马甲':'Fashion vest','纯棉休闲短袖T恤男女':'Unisex cotton short-sleeved T-shirt'};raw=chineseTitles[raw]||raw;const keep=[];let value=raw.replace(/\b(?:Off[ -]White|The North Face|On Running|Nike Tech Fleece|Tech Fleece|Classic Mini|Classic Flap|New Balance|Fear of God|Chrome Hearts|Stone Island|Palm Angels|Golden Goose|Black Cat|White Cement|University Blue|Air Force 1|Air Jordan|Air Max|Louis Vuitton|Saint Laurent|Canada Goose|Under Armour|True Religion|Ture Religion)\b/gi,v=>{keep.push(v);return '\uE000'+(keep.length-1)+'\uE001'});
value=value.replace(/(jeans)(?=loose|baggy)/gi,'$1 ').replace(/(sweatshirts?|hoodies?|vests?|jackets?|pants?|t-shirts?)(?=sweatshirts?|hoodies?|vests?|jackets?|pants?|t-shirts?)/gi,'$1 / ');
const col={de:1,fr:2,es:3,it:4,pt:5,pl:6};if(l!=='en')value=value.replace(TITLE_PATTERN,w=>{let r=TITLE_ROWS.find(r=>new RegExp('^(?:'+r[0]+')$','i').test(w));return l==='nl'?(NL_WORDS[r?.[0]]||dutchFallback(w)):r?.[col[l]]||w});
return value.replace(/\uE000(\d+)\uE001/g,(_,i)=>keep[+i]).replace(/^shoes(?=-)/i,l==='en'?'Shoes':COPY[l][15]);}
function dutchFallback(w){const m={shoe:'schoen',shoes:'schoenen',sneaker:'sneaker',sneakers:'sneakers',sweatshirt:'sweater',sweatshirts:'sweaters',hoodie:'hoodie',hoodies:'hoodies',sweater:'trui',sweaters:'truien',shirt:'overhemd',shirts:'overhemden','t-shirt':'T-shirt','t-shirts':'T-shirts',pants:'broeken',trousers:'broeken',shorts:'shorts',jacket:'jas',jackets:'jassen',coat:'mantel',coats:'mantels',bag:'tas',bags:'tassen',cap:'pet',caps:'petten',hat:'hoed',hats:'hoeden',belt:'riem',belts:'riemen',wallet:'portemonnee',wallets:'portemonnees',watch:'horloge',watches:'horloges',white:'wit',red:'rood',blue:'blauw',black:'zwart',yellow:'geel',green:'groen',silver:'zilver',gold:'goud',necklace:'halsketting',bracelet:'armband',ring:'ring',socks:'sokken',jersey:'sportshirt',jerseys:'sportshirts'};return m[w.toLowerCase()]||w;}
function sourceQuery(q){for(const r of TITLE_ROWS){if(r.slice(1).some(v=>v.toLowerCase()===q.toLowerCase())||NL_WORDS[r[0]]?.toLowerCase()===q.toLowerCase())return r[0].split('|')[0].replace(/\[.*?\]/g,' ').replace(/\?/g,'').replace(/\\s/g,' ')}return q;}
